import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES=sorted((ROOT/'questions/science').glob('question-science-content-bb-iv-2-*.json'),key=lambda p:int(p.stem.rsplit('-',1)[1]))
ITEMS=[
('卡路里定義','在國中常用的熱量定義中，1 cal約表示什麼？',['使1 g水升高1℃所需的熱量','使1 kg鐵升高100℃','1 g水凝固放出的所有熱','1 J的另一個名稱'],'A','1 cal傳統上定義為使1 g水升高1℃所需的熱量，實際值會依定義條件略有差異。'),
('焦耳換算','若取1 cal≈4.2 J，50 cal約等於多少J？',['11.9 J','46.2 J','210 J','4200 J'],'C','50×4.2=210 J。'),
('升溫熱量','取水的比熱1 cal/(g·℃)，100 g水升高5℃需吸收多少熱量？',['20 cal','105 cal','500 cal','2000 cal'],'C','Q=mcΔT=100×1×5=500 cal。'),
('比熱意義','同質量、吸收相同熱量時，甲的溫升比乙小，表示甲的比熱？',['較大','較小','一定為零','與溫升無關'],'A','Q=mcΔT；在m與Q相同時，ΔT較小代表c較大。'),
('熱量比較','兩杯水質量相同，比熱相同；甲升高10℃、乙升高20℃，吸收熱量比較為何？',['甲為乙的一半','甲為乙的兩倍','兩者相同','無法比較'],'A','Q=mcΔT，其他條件相同時熱量與溫升成正比，甲為乙的一半。'),
('質量反推','水比熱1 cal/(g·℃)，吸收300 cal升高3℃，水質量為多少？',['10 g','50 g','100 g','900 g'],'C','m=Q/(cΔT)=300÷(1×3)=100 g。'),
('單位判讀','熱量的SI單位為焦耳；下列哪項表示能量單位的正確換算？',['1 cal≈4.2 J','1 cal≈0.24 J','1 J≈4.2 cal','1 kcal=4.2 J'],'A','常用近似為1 cal≈4.2 J，因此1 J約0.24 cal。'),
('熱容量','兩物體質量與材料不同，不能只看溫度改變判斷吸收熱量，還需知道？',['比熱與質量','顏色與形狀','容器品牌','聲音大小'],'A','Q=mcΔT，熱量取決於質量、比熱與溫度變化。'),
('冷卻熱量','一物體放出熱量使周圍升溫，若只看物體本身，熱量變化應記為？',['吸收正熱量','放出熱量，可視為熱量流出','熱量變成零','質量增加'],'B','熱由物體流向環境，物體本身內能下降；計算時須明確正負號約定。'),
('公式條件','使用Q=mcΔT計算顯熱時，ΔT應代表什麼？',['末溫減初溫的溫度變化量','物體質量','沸點數值','熱傳時間本身'],'A','ΔT是溫度改變量；若只發生相變，還需使用潛熱公式而非直接套顯熱公式。'),
]
for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先確認熱量單位與題目給的m、c、ΔT，再用Q=mcΔT或單位換算；本題聚焦於{topic}。'; d['solutionSteps']=['先列出質量m、比熱c、溫度變化ΔT與熱量單位。','判斷是定義／換算題，或使用Q=mcΔT；必要時先把cal與J換成同一單位。',f'代入公式、整理未知量或比較比例，得到答案{ans}。',f'回看解析：{ex}','最後確認顯熱計算不誤用於相變，且答案單位與正負方向一致。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的熱量單位、比熱、Q=mcΔT與單位換算方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
